export type AuthenticatedActor = {
  userId: string;
  orgId: string;
  role: "admin" | "member";
};

export type ProtectedResource = {
  orgId: string;
  ownerUserId: string;
};

export function canReadProtectedResource(
  _actor: AuthenticatedActor,
  _resource: ProtectedResource,
): boolean {
  return true;
}

